static void playgroundBackendRegressions() {
    auto config=Playground::example();config["competitions"]=16;config["athletes"]=12;config["focus"]=5;config["rounds"]=QJsonArray{12,6};config["sampleLimit"]=4;config["threads"]=1;config["targets"]=QJsonArray();auto initial=config["parameters"].toObject();initial["clock.mode"]=1;config["parameters"]=initial;
    config["variants"]=QJsonArray{QJsonObject{{"name","A"},{"changes",QJsonObject()}},QJsonObject{{"name","B"},{"changes",QJsonObject()}}};QString error;
    check(Playground::validate(config,error),qPrintable("v2 config: "+error));
    const auto before=config;auto report=Playground::run(config,{});check(config==before && report["engineVersion"].toInt()==2 && report["completed"].toInt()==16,"v2 run isolated and complete");
    auto variants=report["variants"].toArray();check(variants[0].toObject()["distance"]==variants[1].toObject()["distance"] && variants[1].toObject()["pairedDistance"].toObject()["mean"].toDouble()==0,"identical variants share seeds exactly");
    config["threads"]=4;auto parallel=Playground::run(config,{});for(int i=0;i<2;++i)check(variants[i].toObject()["distance"].toObject()["histogram"]==parallel["variants"].toArray()[i].toObject()["distance"].toObject()["histogram"] && variants[i].toObject()["samples"]==parallel["variants"].toArray()[i].toObject()["samples"],"worker count preserves samples and distributions");
    auto replay=Playground::replay(config,1,2);check(replay==Playground::replay(config,1,2),"deterministic replay");auto retained=variants[1].toObject()["samples"].toArray()[2].toObject();QJsonObject focusRow;for(const auto &entry:replay["jumps"].toArray()){auto j=entry.toObject();if(j["athlete"].toInt()==5){focusRow=j;break;}}check(retained["jumps"].toArray().first().toObject()==focusRow,"replay uses same seed and weather as retained sample");
    auto p=Playground::valuesFor(config,1);auto row=focusRow;auto detail=row["detail"].toObject();check(detail["engineVersion"].toInt()==2 && !detail["exposures"].toArray().isEmpty(),"real v2 exposure captured");
    SimulationV2::Engine engine(Playground::engineParameters(p));SimulationV2::JumpRequest request;request.athlete=Playground::athleteInput(p,"athlete");request.hill=Playground::hillInput(p);request.event=SimulationV2::EventKind::Competition;request.startSeconds=row["startSeconds"].toDouble();request.scoring.juryGate=request.scoring.referenceGate=replay["gate"].toInt();
    // Reconstruct the separate field seed for the selected competition.
    auto mix=[](quint64 x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);};
    auto contest=mix(config["seed"].toString().toULongLong()^mix(2));SimulationV2::ContinuousWeather weather(mix(contest^0x57494e44ULL),Playground::windParameters(p),Playground::precipitationParameters(p));CompetitionRules rules;rules.setWindMeasurementType(p["rules.measurement"].toInt());SimulationV2::FieldWindMeasurement measurement(request.hill.k,rules,Playground::measurementParameters(p));SimulationV2::SeededRandom rng(detail["seed"].toString().toULongLong());auto actual=engine.simulate(request,rng,weather,measurement);check(actual.measuredDistance==row["distance"].toDouble() && actual.score.total==row["points"].toDouble(),"playground is numerically identical to the full v2 engine");
    auto changes=QJsonObject{{"athlete.overall",30}};auto v=config["variants"].toArray();auto second=v[1].toObject();second["changes"]=changes;v[1]=second;config["variants"]=v;auto weaker=Playground::run(config,{});check(weaker["variants"].toArray()[1].toObject()["pairedDistance"].toObject()["mean"].toDouble()<-10,"OVR tuning changes actual distance");
    auto controlled=config;controlled["parameters"]=QJsonObject{{"clock.mode",0}};auto fixed=Playground::replay(controlled,0,0);for(auto j:fixed["jumps"].toArray())check(j.toObject()["startSeconds"].toDouble()==0,"controlled weather holds takeoff time fixed");check(replay["jumps"].toArray().last().toObject()["startSeconds"].toDouble()>0,"contest mode advances common weather clock");
    auto invalid=config;invalid["schema"]=1;check(!Playground::validate(invalid,error),"reject legacy schema instead of pretending v2");invalid=config;invalid["parameters"]=QJsonObject{{"engine.randomness",1}};check(!Playground::validate(invalid,error),"reject old technical parameters");invalid=config;invalid["parameters"]=QJsonObject{{"wind.trendPeriodSeconds",10},{"wind.trendTransitionSeconds",8}};check(!Playground::validate(invalid,error),"cross-field wind validation");
    auto dsq=config;dsq["parameters"]=QJsonObject{{"dsq",1},{"rules.dsq",0}};auto legal=Playground::replay(dsq,0,0);for(const auto &j:legal["jumps"].toArray())check(!j.toObject()["dsq"].toBool(),"disabled DSQ rules override configured probability");
    auto canceled=std::make_shared<Playground::Control>();canceled->canceled.store(true);check(Playground::run(config,canceled)["completed"].toInt()==0,"cancel before batch preserves no partial pairs");
    auto d=Playground::diagnostics(config,0);check(d["landing"].toArray().size()==81 && d["grid"].toArray().size()==241*49 && d["heatmap"].toString().startsWith("data:image/png"),"landing and full space-time field diagnostics");for(auto c:d["landing"].toArray()){double sum=0;for(auto x:c.toObject()["probabilities"].toArray())sum+=x.toDouble();check(std::abs(sum-1)<1e-10,"landing probabilities normalized");}
    auto registry=Playground::parameters();QSet<QString> keys;for(auto item:registry){auto def=item.toObject();keys.insert(def["key"].toString());}check(registry.size()==keys.size() && registry.size()>150 && keys.contains("flight.rainHeavyExponent") && keys.contains("wind.trendAmplitude") && keys.contains("quality.regularNegative.3") && keys.contains("curve.takeoff.7"),"full scalar/array/curve registry without duplicates");
    QTemporaryDir directory;check(Playground::exportReport(report,directory.path()+"/run",error),"v2 export");check(!Playground::exportReport(report,directory.path()+"/run",error),"exports never overwrite a report");
    qInfo()<<"PASS: playground v2 engine equivalence, paired seeds, clocks, parallelism, diagnostics, cancellation, validation and export";
}

