    QStandardPaths::setTestModeEnabled(true);main.show();
    {AppSettingsWindow settings(&main);settings.setupLanguagesComboBox();render(&settings,"playground-settings-entry");check(item(scene(&settings)->rootObject(),"action-openSimulationPlayground"),"playground is visible directly in engine settings");clickControl(scene(&settings),"action-openSimulationPlayground");QTest::qWait(100);auto *opened=settings.findChild<QDialog *>("simulationPlayground");check(opened && opened->findChild<PlaygroundController *>(),"real settings action opens the playground workspace");opened->reject();QTest::qWait(50);settings.reject();}
    main.show();main.resize(1280,900);PlaygroundWindow window(&main);render(&window,"playground-setup",true);auto *controller=window.findChild<PlaygroundController *>();check(controller && item(scene(&window)->rootObject(),"playgroundScreen"),"dedicated playground workspace opens");auto config=Playground::example();config["competitions"]=12;config["threads"]=3;config["athletes"]=12;config["focus"]=5;config["rounds"]=QJsonArray{12,6};config["sampleLimit"]=3;check(controller->configure(config.toVariantMap()),"UI accepts controlled experiment fixture");clickControl(scene(&window),"playgroundRun");check(controller->busy() || controller->report().value("completed").toInt()==12,"real run button starts background computation");controller->setAnalysisVariant(1);QElapsedTimer wait;wait.start();while(controller->busy() && wait.elapsed()<15000)QTest::qWait(20);check(!controller->busy() && controller->report().value("completed").toInt()==12,qPrintable(QString("UI background experiment completes (busy=%1, completed=%2, message=%3)").arg(controller->busy()).arg(controller->report().value("completed").toInt()).arg(controller->message())));render(&window,"playground-comparison",true);auto *root=item(scene(&window)->rootObject(),"playgroundScreen");root->setProperty("resultVariant",1);root->setProperty("resultAthlete",3);root->setProperty("section",2);QTest::qWait(100);check(root->property("resultVariant").toInt()==1 && item(scene(&window)->rootObject(),"playgroundResultVariant")->property("currentIndex").toInt()==1 && root->property("resultAthlete").toInt()==3,"analysis preserves chosen variant and athlete when switching views");render(&window,"playground-athlete",true);root->setProperty("section",3);QTest::qWait(100);clickControl(scene(&window),"playgroundReplay");wait.restart();while(controller->busy() && wait.elapsed()<15000)QTest::qWait(20);check(!controller->busy() && controller->replayResult().value("standings").toList().size()==12,"real replay action shows full competition standings");render(&window,"playground-replay",true);root->setProperty("section",4);QTest::qWait(80);check(!controller->history().isEmpty(),"completed experiments are retained in history");root->setProperty("section",5);QTest::qWait(80);render(&window,"playground-cli");controller->setAnalysisVariant(1);wait.restart();while(controller->previewBusy() && wait.elapsed()<30000)QTest::qWait(20);check(!controller->diagnostics().isEmpty() && !controller->diagnostics().contains("error"),"current analysis completes");for(int section:{6,7,8,9}){root->setProperty("section",section);QTest::qWait(80);render(&window,QString("playground-analysis-%1").arg(section),true);}config["competitions"]=100000;check(controller->configure(config.toVariantMap()),"large closing fixture accepted");const int histories=controller->history().size();controller->start();QTest::qWait(30);window.reject();wait.restart();while(controller->busy() && wait.elapsed()<15000)QTest::qWait(20);QTest::qWait(50);check(!controller->busy() && !window.isVisible() && controller->report().value("canceled").toBool() && controller->history().size()>histories,"closing a running playground cancels safely and persists completed comparisons before leaving");qInfo()<<"PASS: playground setup, real run/replay, charts, athlete perspective, history, CLI guidance and responsive themes";
